import{_ as s,C as i,o,c as r,j as t,a as n,E as d,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const w=JSON.parse('{"title":"REST API","description":"","frontmatter":{},"headers":[],"relativePath":"admin/api.md","filePath":"admin/api.md"}'),h={name:"admin/api.md"};function c(p,e,k,u,g,m){const a=i("Badge");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"rest-api",tabindex:"-1"},[n("REST API "),t("a",{class:"header-anchor",href:"#rest-api","aria-label":'Permalink to "REST API"'},"​")],-1)),d(a,{type:"built",text:"Built"}),e[1]||(e[1]=l(` The web app, the launcher and the review bot all talk to the same HTTP API under <code>/api/v1</code>. You can use it for scripts and integrations.<div class="warning custom-block"><p class="custom-block-title">Not a stable contract yet</p><p>Octryx AI is 0.0.1-alpha. The API can change between versions without notice. This page lists only the routes we have checked in the code; there are many more, mostly for the web app.</p></div><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p><code>POST /api/v1/auth/login</code> takes the form fields <code>username</code> and <code>password</code> and answers with <code>access_token</code>, <code>token_type</code> (<code>bearer</code>) and <code>refresh_token</code>. Send the token as <code>Authorization: Bearer &lt;access_token&gt;</code>. A failed login is rate-limited and recorded in the audit log. Where an installation allows only single sign-on, a password login is refused.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Octryx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/auth/login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> username=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> password=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passwor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Coding clients sign in over OAuth instead: see <a href="/docs/connections/mcp#octryx-ai-as-an-mcp-server">MCP servers</a>.</p><h2 id="main-routes" tabindex="-1">Main routes <a class="header-anchor" href="#main-routes" aria-label="Permalink to &quot;Main routes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>GET /api/v1/health</code></td><td>Is the platform up? Answers without a sign-in.</td></tr><tr><td><code>GET /api/v1/observability/health</code></td><td>The detailed component checks. Admins only.</td></tr><tr><td><code>GET /api/v1/workflow-runs/startable</code></td><td>The workflows a run can start, for a Workspace (<code>project_id</code>) or a work item (<code>work_item_id</code>). For a work item it also names the workflow the next run would start with; nothing starts by itself.</td></tr><tr><td><code>POST /api/v1/workflow-runs</code></td><td>Start a run: the workflow, the Workspace, optionally a work item, repository, branch and where it runs. It is refused for a Workspace or work item you may not start runs in.</td></tr><tr><td><code>GET /api/v1/workflow-runs</code></td><td>List runs, filtered by status, work item or Workspace.</td></tr><tr><td><code>GET /api/v1/workflow-runs/{run_id}</code></td><td>One run, with <code>/events</code> for its timeline.</td></tr><tr><td><code>GET /api/v1/flows</code></td><td>The published workflows (<code>include_inactive=true</code> also lists those that are off).</td></tr><tr><td><code>POST /api/v1/flows/{flow_id}/active</code></td><td>Switch a workflow on or off with <code>{&quot;active&quot;: true}</code> or <code>false</code>. Platform admins only.</td></tr><tr><td><code>/api/v1/workspaces/{workspace_id}/check-proposals</code></td><td>The checks proposed from corrections. Members read; approving, changing and rejecting need more rights. See <a href="/docs/review-bot/learning">Learning from corrections</a>.</td></tr><tr><td><code>GET /metrics</code></td><td>Prometheus metrics. See <a href="/docs/install/metrics">Metrics</a>.</td></tr></tbody></table><p>The MCP server for coding clients has its own endpoint, <code>/api/v1/mcp/knowledge-protocol/mcp</code>. See <a href="/docs/connections/mcp">MCP servers</a>.</p><h2 id="rules-that-apply-to-every-call" tabindex="-1">Rules that apply to every call <a class="header-anchor" href="#rules-that-apply-to-every-call" aria-label="Permalink to &quot;Rules that apply to every call&quot;">​</a></h2><ul><li>Every call is checked against the caller&#39;s rights in the Workspace, the same as in the web app.</li><li>Sign-ins and refused requests are audited. See <a href="/docs/admin/governance">Governance</a>.</li></ul>`,13))])}const f=s(h,[["render",c]]);export{w as __pageData,f as default};
